package edu.carroll.cs341.web.form;

import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * Form class used to collect and validate a user's name.
 * <p>
 * Ensures that the submitted name is not null, contains between
 * 2 and 40 characters.
 * <p>
 * <b>Sources Used:</b>
 * <ul>
 *   <li>ChatGPT – Assisted with generating Javadoc comments for this file
 *   in conjunction with Max Montowski.
 *   All comments were reviewed by the author. No code was generated by ChatGPT.</li>
 * </ul>
 */
public class EditNameForm {

    /**
     * The name submitted by the user.
     */
    @NotNull(message = "Name is required")
    @Size(min = 2, message = "Name must be longer than 1 character")
    @Size(max = 40, message = "Name cannot be longer than 40 characters")
    private String name;

    /**
     * Retrieves the submitted name.
     *
     * @return the user's name
     */
    public String getName() {
        return name;
    }

    /**
     * Updates the submitted name.
     *
     * @param name the name to set
     */
    public void setName(String name) {
        this.name = name;
    }
}
